SELECT id, tenant, principal_id, workspace_request, model_provider_request, hub_provider_request, handoff_id, configure_request, rotate_request, family_id, ready, provisioning AS "provisioning: Json<ComputerProvisionSpec>", operation_id, operation_started_at, operation_provisioning AS "operation_provisioning: Json<ComputerProvisionSpec>", operation_notice_shown, failure AS "failure: Json<ComputerFailure>", update_notice AS "update_notice: Json<UpdateNotice>", collected_at FROM hub.computer WHERE id = $1 AND tenant = $2 AND principal_id = $3 FOR UPDATE
